using DadoRetail.Domain.Common;namespace DadoRetail.Domain.Inventory;public enum InventoryStatus{Draft,Counting,AwaitingApproval,Approved,Cancelled}public sealed class InventoryDocument:Entity{private InventoryDocument(){}public InventoryDocument(Guid warehouseId,string number){if(warehouseId==Guid.Empty)throw new ArgumentException("Warehouse is required",nameof(warehouseId));if(string.IsNullOrWhiteSpace(number))throw new ArgumentException("Inventory number is required",nameof(number));WarehouseId=warehouseId;Number=number.Trim();}public Guid WarehouseId{get;private set;}public string Number{get;private set;}=null!;public InventoryStatus Status{get;private set;}=InventoryStatus.Draft;public DateTime? ApprovedAtUtc{get;private set;}public Guid? ApprovedByUserId{get;private set;}public ICollection<InventoryLine> Lines{get;private set;}=new List<InventoryLine>();public void Start(){if(Status!=InventoryStatus.Draft)throw new InvalidOperationException("Only draft inventory can be started");Status=InventoryStatus.Counting;MarkUpdated();}public void Count(Guid productId,decimal bookQuantity,decimal actualQuantity){if(Status!=InventoryStatus.Counting)throw new InvalidOperationException("Inventory is not in counting state");if(actualQuantity<0)throw new ArgumentOutOfRangeException(nameof(actualQuantity));var line=Lines.FirstOrDefault(x=>x.ProductId==productId);if(line is null)Lines.Add(new InventoryLine(Id,productId,bookQuantity,actualQuantity));else line.SetActual(actualQuantity);MarkUpdated();}public void Submit(){if(Status!=InventoryStatus.Counting||Lines.Count==0)throw new InvalidOperationException("Inventory must contain counted items");Status=InventoryStatus.AwaitingApproval;MarkUpdated();}public void Approve(Guid userId){if(Status!=InventoryStatus.AwaitingApproval)throw new InvalidOperationException("Inventory is not awaiting approval");Status=InventoryStatus.Approved;ApprovedByUserId=userId;ApprovedAtUtc=DateTime.UtcNow;MarkUpdated();}public void Cancel(){if(Status==InventoryStatus.Approved)throw new InvalidOperationException("Approved inventory cannot be cancelled");if(Status==InventoryStatus.Cancelled)return;Status=InventoryStatus.Cancelled;MarkUpdated();}}
public sealed class InventoryLine:Entity{private InventoryLine(){}internal InventoryLine(Guid inventoryId,Guid productId,decimal bookQuantity,decimal actualQuantity){InventoryId=inventoryId;ProductId=productId;BookQuantity=bookQuantity;ActualQuantity=actualQuantity;}public Guid InventoryId{get;private set;}public Guid ProductId{get;private set;}public decimal BookQuantity{get;private set;}public decimal ActualQuantity{get;private set;}public decimal Difference=>ActualQuantity-BookQuantity;internal void SetActual(decimal q){ActualQuantity=q;MarkUpdated();}}
